import { atlasesOf, effectNames, idleAtlasOf, portraitOf, urlsOf } from '../strip-urls';
import type { Atlas, FighterArt } from '../types';
import { SAPHIR_CELLS } from './cells';
import { SAPHIR_CLIPS } from './clips';
import { SAPHIR_SHEETS } from './sheets';

/** Strips generated by `npm run sprites` (tools/sprites), one folder per colorway. */
const MAIN = import.meta.glob<string>('./main/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT = import.meta.glob<string>('./alt/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** Front effects of the strips that have some (energy, flashes, sparks, dust). */
const MAIN_FX = import.meta.glob<string>('./main/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_FX = import.meta.glob<string>('./alt/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});

/**
 * The atlas written next to each image (tools/sprites/atlas.ts): where its frames are, cut to what
 * they draw and packed. The fight loads it with the image.
 */
const MAIN_ATLASES = import.meta.glob<string>('./main/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_ATLASES = import.meta.glob<string>('./alt/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** The idle's atlases, bundled: the select screen shows its frames at once. */
const IDLE_ATLASES = import.meta.glob<Atlas>('./*/idle.json', { eager: true, import: 'default' });

const SHARED = {
  // Her hat, her face and her raised fists, on the character select screen.
  portrait: { x: 12, y: 0, size: 58 },
  sheets: SAPHIR_SHEETS,
  clips: SAPHIR_CLIPS,
  cells: SAPHIR_CELLS,
};

/** The record dealer: a cream pantsuit and felt hat, a green band and energy (docs/saphir.md §8). */
export const SAPHIR: FighterArt = {
  key: 'saphir',
  urls: urlsOf(MAIN, 'main', SAPHIR_SHEETS),
  fx: urlsOf(MAIN_FX, 'main/fx', effectNames(SAPHIR_SHEETS, SAPHIR_CLIPS)),
  atlases: atlasesOf(MAIN_ATLASES, 'main', SAPHIR_SHEETS, effectNames(SAPHIR_SHEETS, SAPHIR_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'main', SAPHIR_CLIPS.idle.sheet),
  ...portraitOf(MAIN, 'main'),
  ...SHARED,
};
/** The black dinner suit, the lilac band and energy: player 2 in a mirror match. */
export const SAPHIR_ALT: FighterArt = {
  key: 'saphir-alt',
  urls: urlsOf(ALT, 'alt', SAPHIR_SHEETS),
  fx: urlsOf(ALT_FX, 'alt/fx', effectNames(SAPHIR_SHEETS, SAPHIR_CLIPS)),
  atlases: atlasesOf(ALT_ATLASES, 'alt', SAPHIR_SHEETS, effectNames(SAPHIR_SHEETS, SAPHIR_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'alt', SAPHIR_CLIPS.idle.sheet),
  ...portraitOf(ALT, 'alt'),
  ...SHARED,
};
